                        KEY `isThuong_index` (`isThuong`) USING BTREE,
                        KEY `isDaily_index` (`isDaily`) USING BTREE,
                        KEY `isSuper_index` (`isSuper`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=276 DEFAULT CHARSET=utf8 ROW_FORMAT=DYNAMIC;
