DELIMITER ;;
CREATE DEFINER=`root`@`%` PROCEDURE `tx_get_top_win_md5`(IN money_type TINYINT)
BEGIN
  SET
@min_id_today = (SELECT `value` FROM key_value WHERE updated_at = CURDATE() AND `key` = CONCAT('taixiu_md5_', money_type));
    IF
ISNULL(@min_id_today) THEN
UPDATE key_value
SET `value`    = (SELECT min(id)
                  FROM transaction_tai_xiu_md5
                  WHERE `timestamp` >= CURDATE()
                    AND transaction_tai_xiu_md5.money_type = money_type),
    updated_at = CURDATE()
WHERE `key` = CONCAT('taixiu_md5_', money_type);
SET
@min_id_today = (SELECT `value` FROM key_value WHERE updated_at = CURDATE() AND `key` = CONCAT('taixiu_md5_', money_type));
END IF;

SELECT user_name, SUM(total_exchange) as money
FROM transaction_tai_xiu_md5
WHERE id >= @min_id_today
  AND transaction_tai_xiu_md5.money_type = money_type
GROUP BY user_name
HAVING sum(total_exchange) > 0
ORDER BY money DESC LIMIT 0, 10;
END ;;
